+        let minDot = 1e9;
+        for (let j = 0; j < 4; j++) {
+          const wv = bodyB.getWorldVertex(j);
+          const d = (wv.x - bodyA.pos.x) * axis.x + (wv.y - bodyA.pos.y) * axis.y;
+          if (d < minDot) minDot = d;
+        }
