+      if (d0 * d1 < 0) {
+        const alpha = d0 / (d0 - d1);
+        vOut[numOut] = {
+          x: vIn[0].x + alpha * (vIn[1].x - vIn[0].x),
+          y: vIn[0].y + alpha * (vIn[1].y - vIn[0].y),
+          id: clipEdgeId
