+      const incV0 = incBody.getWorldVertex(incFaceIdx);
+      const incV1 = incBody.getWorldVertex((incFaceIdx + 1) % 4);
+      let incSegment = [
+        { x: incV0.x, y: incV0.y, id: incFaceIdx },
+        { x: incV1.x, y: incV1.y, id: (incFaceIdx + 1) % 4 }
+      ];
