+      // Reference face side planes
+      const sideAxis = new Vec2(-normal.y, normal.x);
+      const sideOffset1 = refBody.pos.x * sideAxis.x + refBody.pos.y * sideAxis.y + (Math.abs(normal.y) > 0.5 ? refBody.halfW : refBody.halfH);
