+    // --- Spatial Hash Broadphase ---
+    class SpatialGrid {
+      constructor(cellSize = 0.8) {
+        this.cellSize = cellSize;
+        this.grid = new Map();
+      }
+      clear() { this.grid.clear(); }
+      hash(x, y, layer) {
+        return `${Math.floor(x / this.cellSize)}_${Math.floor(y / this.cellSize)}_${layer}`;
+      }
+      insert(body) {
+        const x0 = Math.floor(body.aabb.minX / this.cellSize);
+        const x1 = Math.floor(body.aabb.maxX / this.cellSize);
+        const y0 = Math.floor(body.aabb.minY / this.cellSize);
+        const y1 = Math.floor(body.aabb.maxY / this.cellSize);
+
+        const l0 = body.kind === 'car' ? 0 : body.layer;
+        const l1 = body.kind === 'car' ? CONFIG.wallLayers - 1 : body.layer;
+
+        for (let x = x0; x <= x1; x++) {
+          for (let y = y0; y <= y1; y++) {
+            for (let l = l0; l <= l1; l++) {
+              const k = `${x}_${y}_${l}`;
+              let bucket = this.grid.get(k);
+              if (!bucket) { bucket = []; this.grid.set(k, bucket); }
+              bucket.push(body);
+            }
+          }
+        }
+      }
+    }
