+    // --- Particle System ---
+    class Particle {
+      constructor() {
+        this.pos = new Vec2();
+        this.vel = new Vec2();
+        this.rot = 0;
+        this.rotSpeed = 0;
+        this.size = 1;
+        this.color = '#fff';
+        this.alpha = 1;
+        this.life = 0;
+        this.maxLife = 1;
+        this.type = 'dust'; // 'dust', 'spark', 'debris', 'smoke'
+        this.active = false;
+      }
+    }
