+          const p = this.pool.find(item => !item.active);
+          if (!p) break;
+          p.active = true;
+          p.type = type;
+          p.pos.set(x + (Math.random() - 0.5) * 0.2, y + (Math.random() - 0.5) * 0.2);
+          
+          const angle = Math.random() * Math.PI * 2;
+          const speed = (Math.random() * 0.7 + 0.3) * (type === 'spark' ? 8 : 4);
+          p.vel.set(vx + Math.cos(angle) * speed, vy + Math.sin(angle) * speed);
+          p.rot = Math.random() * Math.PI * 2;
+          p.rotSpeed = (Math.random() - 0.5) * 15;
+          p.color = color;
+          p.alpha = 1.0;
+          p.life = 0;
+          
+          if (type === 'dust') {
+            p.maxLife = 0.8 + Math.random() * 0.8;
+            p.size = 0.08 + Math.random() * 0.12;
+          } else if (type === 'spark') {
+            p.maxLife = 0.2 + Math.random() * 0.3;
+            p.size = 0.03 + Math.random() * 0.04;
+          } else if (type === 'debris') {
+            p.maxLife = 1.5 + Math.random() * 1.0;
+            p.size = 0.04 + Math.random() * 0.08;
+          } else if (type === 'smoke') {
+            p.maxLife = 1.2 + Math.random() * 0.8;
+            p.size = 0.15 + Math.random() * 0.2;
