+                  kind: 'brick',
+                  x: x,
+                  y: y,
+                  w: brickW,
+                  h: brickH,
+                  mass: brickMass,
+                  friction: CONFIG.brickFriction,
+                  restitution: CONFIG.brickRestitution,
+                  layer: l,
+                  shade: (Math.sin(c * 23 + r * 47 + l * 19) * 0.15)
