+                kind: 'brick',
+                x: wallOriginX + (cols - 0.5) * brickW + halfBrickW * 0.5,
+                y: y,
+                w: halfBrickW,
+                h: brickH,
+                mass: brickMass * 0.5,
+                friction: CONFIG.brickFriction,
+                restitution: CONFIG.brickRestitution,
