+            }
+          }
+        }
+
+        // 5. Iterative Velocity Impulse Solver
+        const VELOCITY_ITERS = 14;
+        for (let iter = 0; iter < VELOCITY_ITERS; iter++) {
+          for (const m of activeManifolds) {
+            const bA = m.bodyA, bB = m.bodyB;
+            const normal = m.normal, tangent = m.tangent;
+
+            for (let i = 0; i < m.pointCount; i++) {
+              const cp = m.points[i];
+              const rA = cp.rA, rB = cp.rB;
+
+              // Relative velocity at contact point
+              const vA = vecAdd(bA.vel, vecCrossSV(bA.angularVel, rA));
+              const vB = vecAdd(bB.vel, vecCrossSV(bB.angularVel, rB));
+              const relV = vecSub(vB, vA);
+
+              // --- A. Tangent Friction Impulse (Coulomb Law) ---
+              const vt = relV.dot(tangent);
+              let lambdaT = cp.tangentMass * (-vt);
+              const maxFriction = m.friction * cp.normalImpulse;
+              const newTangentImpulse = Math.max(-maxFriction, Math.min(maxFriction, cp.tangentImpulse + lambdaT));
