+              const Pt = vecScale(tangent, lambdaT);
+              if (bA.type === 'dynamic') {
+                bA.vel.sub(vecScale(Pt, bA.invMass));
+                bA.angularVel -= bA.invInertia * rA.cross(Pt);
+              }
+              if (bB.type === 'dynamic') {
+                bB.vel.add(vecScale(Pt, bB.invMass));
+                bB.angularVel += bB.invInertia * rB.cross(Pt);
+              }
+
+              // --- B. Normal Contact Impulse ---
+              const vA2 = vecAdd(bA.vel, vecCrossSV(bA.angularVel, rA));
+              const vB2 = vecAdd(bB.vel, vecCrossSV(bB.angularVel, rB));
+              const relV2 = vecSub(vB2, vA2);
+              const vn = relV2.dot(normal);
