+              const Pn = vecScale(normal, lambdaN);
+              if (bA.type === 'dynamic') {
+                bA.vel.sub(vecScale(Pn, bA.invMass));
+                bA.angularVel -= bA.invInertia * rA.cross(Pn);
+              }
+              if (bB.type === 'dynamic') {
+                bB.vel.add(vecScale(Pn, bB.invMass));
+                bB.angularVel += bB.invInertia * rB.cross(Pn);
+              }
+            }
+          }
+        }
