+
+    // --- Camera & Viewport Controller ---
+    class Camera {
+      constructor() {
+        this.x = 12.0;
+        this.y = 2.0;
+        this.zoom = 1.0;
+        this.targetX = 12.0;
+        this.targetY = 2.0;
+        this.targetZoom = 1.0;
+        this.autoFollow = true;
+        this.shake = 0;
+      }
+
+      update(carPos, state, dt) {
+        if (this.autoFollow && carPos) {
+          if (state === 'READY') {
+            this.targetX = 10.0;
+            this.targetY = 2.2;
+            this.targetZoom = 1.0;
+          } else if (state === 'ACCELERATING') {
+            this.targetX = carPos.x + 4.5;
+            this.targetY = 2.2;
+            this.targetZoom = 1.05;
+          } else if (state === 'IMPACT') {
+            this.targetX = 17.5;
+            this.targetY = 2.4;
+            this.targetZoom = 1.15;
+            this.shake = 0.35;
+          } else {
+            // Settling or Settled
+            this.targetX = 18.0;
+            this.targetY = 2.2;
+            this.targetZoom = 0.95;
+          }
+        }
