+        // Smooth camera lerp
+        this.x += (this.targetX - this.x) * Math.min(1.0, dt * 6.0);
+        this.y += (this.targetY - this.y) * Math.min(1.0, dt * 6.0);
+        this.zoom += (this.targetZoom - this.zoom) * Math.min(1.0, dt * 6.0);
+
+        if (this.shake > 0) {
+          this.shake = Math.max(0, this.shake - dt * 1.5);
+        }
+      }
