+        ctx.fillRect(0, groundScreen.y, w, h - groundScreen.y);
+
+        // Asphalt Top Line
+        ctx.strokeStyle = '#38bdf8';
+        ctx.lineWidth = 2;
+        ctx.beginPath();
+        ctx.moveTo(0, groundScreen.y);
+        ctx.lineTo(w, groundScreen.y);
