+        const stripeW = 20;
+        for (let x = 0; x < w; x += stripeW * 2) {
+          ctx.fillStyle = '#fbbf24';
+          ctx.fillRect(x, groundScreen.y, stripeW, curbH);
+          ctx.fillStyle = '#1e293b';
+          ctx.fillRect(x + stripeW, groundScreen.y, stripeW, curbH);
+        }
+
+        // Track Distance Measurement Markings
+        ctx.strokeStyle = 'rgba(255, 255, 255, 0.15)';
+        ctx.lineWidth = 2;
+        for (let m = 0; m <= 35; m += 5) {
+          const pt = toScreen(m, 0);
+          ctx.beginPath();
+          ctx.moveTo(pt.x, groundScreen.y);
