+        // 5. Render Car
+        if (this.world.car) {
+          this.renderCar(ctx, this.world.car, scale, toScreen);
+        }
+      }
+
+      renderBrickLayer(ctx, bricks, layerIdx, scale, toScreen) {
+        const depthDim = 1.0 - (layerIdx * 0.18);
+        const zOffset = layerIdx * 3; // slight isometric parallax offset
+
+        for (const b of bricks) {
+          const sPos = toScreen(b.pos.x, b.pos.y);
+          ctx.save();
+          ctx.translate(sPos.x + zOffset, sPos.y - zOffset);
+          ctx.rotate(b.angle);
