+          ctx.fillRect(-pw * 0.5, -ph * 0.5, pw, 2);
+          ctx.fillRect(-pw * 0.5, -ph * 0.5, 2, ph);
+
+          // Bottom & Right Shading
+          ctx.fillStyle = `rgba(0, 0, 0, ${0.35 * depthDim})`;
+          ctx.fillRect(-pw * 0.5, ph * 0.5 - 2, pw, 2);
+          ctx.fillRect(pw * 0.5 - 2, -ph * 0.5, 2, ph);
