+        grad.addColorStop(0, '#fde047'); // Bright Crash Test Yellow
+        grad.addColorStop(0.5, '#eab308');
+        grad.addColorStop(1, '#ca8a04');
+
+        ctx.fillStyle = grad;
+        ctx.beginPath();
+        // Aerodynamic Crash Test Vehicle Polygon
+        const frontX = pw * 0.5;
+        const rearX = -pw * 0.5;
+        const roofTop = -ph * 0.5;
+        const hoodTop = -ph * 0.15;
+        const bottomY = ph * 0.35;
+
+        ctx.moveTo(rearX, bottomY);
+        ctx.lineTo(rearX, -ph * 0.25);
+        ctx.lineTo(rearX + pw * 0.2, roofTop);
+        ctx.lineTo(frontX - pw * 0.32, roofTop);
+        ctx.lineTo(frontX - pw * 0.12, hoodTop);
+        ctx.lineTo(frontX, hoodTop + 8);
+        ctx.lineTo(frontX, bottomY);
+        ctx.closePath();
+        ctx.fill();
+
+        // 3. Cabin Windows & Tinted Glass
+        ctx.fillStyle = '#0f172a';
+        ctx.beginPath();
+        ctx.moveTo(rearX + pw * 0.24, roofTop + 4);
+        ctx.lineTo(frontX - pw * 0.34, roofTop + 4);
+        ctx.lineTo(frontX - pw * 0.18, hoodTop + 2);
+        ctx.lineTo(rearX + pw * 0.24, hoodTop + 2);
+        ctx.closePath();
+        ctx.fill();
+
+        // Glass Reflection Streak
+        ctx.fillStyle = 'rgba(255, 255, 255, 0.35)';
+        ctx.beginPath();
+        ctx.moveTo(frontX - pw * 0.28, roofTop + 5);
+        ctx.lineTo(frontX - pw * 0.32, roofTop + 5);
+        ctx.lineTo(frontX - pw * 0.22, hoodTop + 2);
+        ctx.lineTo(frontX - pw * 0.18, hoodTop + 2);
+        ctx.closePath();
+        ctx.fill();
+
+        // Crash Test Dummy Silhouette in Window
+        ctx.fillStyle = '#fbbf24';
+        const dummyX = -pw * 0.05;
+        const dummyY = roofTop + ph * 0.22;
+        ctx.beginPath();
+        ctx.arc(dummyX, dummyY, 7, 0, Math.PI * 2);
+        ctx.fill();
+        ctx.fillStyle = '#0f172a';
+        ctx.beginPath();
+        ctx.arc(dummyX, dummyY, 2, 0, Math.PI * 2);
+        ctx.fill();
+
+        // 4. ISO Crash Test Target Crosshairs (Yellow/Black Quarters)
+        const drawCrosshair = (cx, cy, r) => {
+          ctx.save();
+          ctx.translate(cx, cy);
+          ctx.fillStyle = '#000000';
+          ctx.beginPath();
+          ctx.arc(0, 0, r, 0, Math.PI * 0.5);
+          ctx.lineTo(0, 0);
+          ctx.fill();
+          ctx.beginPath();
+          ctx.arc(0, 0, r, Math.PI, Math.PI * 1.5);
+          ctx.lineTo(0, 0);
+          ctx.fill();
+
+          ctx.fillStyle = '#fbbf24';
+          ctx.beginPath();
+          ctx.arc(0, 0, r, Math.PI * 0.5, Math.PI);
+          ctx.lineTo(0, 0);
+          ctx.fill();
+          ctx.beginPath();
+          ctx.arc(0, 0, r, Math.PI * 1.5, Math.PI * 2);
+          ctx.lineTo(0, 0);
+          ctx.fill();
+
+          ctx.strokeStyle = '#000';
+          ctx.lineWidth = 1;
+          ctx.beginPath();
+          ctx.arc(0, 0, r, 0, Math.PI * 2);
+          ctx.stroke();
+          ctx.restore();
+        };
+
+        drawCrosshair(-pw * 0.2, 0, 10);
+        drawCrosshair(pw * 0.15, 0, 10);
+
+        // Vehicle Identification Decal
+        ctx.fillStyle = '#0f172a';
+        ctx.font = 'bold 11px JetBrains Mono';
+        ctx.fillText('CRASH TEST 01', -pw * 0.35, 12);
+
+        // 5. Headlights & Taillights
+        ctx.fillStyle = '#38bdf8';
+        ctx.shadowColor = '#38bdf8';
+        ctx.shadowBlur = 8;
+        ctx.fillRect(frontX - 4, hoodTop + 6, 4, 12);
+        ctx.shadowBlur = 0;
+
+        ctx.fillStyle = '#ef4444';
+        ctx.fillRect(rearX, -ph * 0.15, 4, 10);
+
+        // 6. Wheels (Front & Rear)
+        const wheelR = ph * 0.24;
+        const frontWheelX = frontX - pw * 0.22;
+        const rearWheelX = rearX + pw * 0.22;
+        const wheelY = bottomY + 2;
+
+        const drawWheel = (wx, wy) => {
+          ctx.save();
+          ctx.translate(wx, wy);
+          const spin = (car.pos.x / (wheelR / scale));
+          ctx.rotate(spin);
+
+          // Tire Rubber
+          ctx.fillStyle = '#1e293b';
+          ctx.beginPath();
+          ctx.arc(0, 0, wheelR, 0, Math.PI * 2);
+          ctx.fill();
+
+          // Alloy Rim
+          ctx.fillStyle = '#94a3b8';
+          ctx.beginPath();
+          ctx.arc(0, 0, wheelR * 0.6, 0, Math.PI * 2);
+          ctx.fill();
+
+          // Rim Spokes
+          ctx.strokeStyle = '#0f172a';
+          ctx.lineWidth = 2;
+          for (let sp = 0; sp < 5; sp++) {
+            const a = (sp / 5) * Math.PI * 2;
+            ctx.beginPath();
+            ctx.moveTo(0, 0);
+            ctx.lineTo(Math.cos(a) * wheelR * 0.58, Math.sin(a) * wheelR * 0.58);
+            ctx.stroke();
+          }
+
+          // Crosshair Hub
+          drawCrosshair(0, 0, wheelR * 0.25);
+          ctx.restore();
+        };
+
+        drawWheel(rearWheelX, wheelY);
+        drawWheel(frontWheelX, wheelY);
+
+        ctx.restore();
+      }
+    }
+
+    // --- Main Application Controller ---
+    class App {
+      constructor() {
+        this.canvas = document.getElementById('simCanvas');
+        this.world = new PhysicsWorld();
+        this.camera = new Camera();
+        this.renderer = new Renderer(this.canvas, this.world, this.camera);
+
+        this.timeScale = 1.0;
+        this.isPaused = false;
+        this.lastTimestamp = performance.now();
+
+        this.initUI();
+        this.bindEvents();
+
+        // Initial setup with mandatory default values
+        this.world.reset();
+        this.updateTelemetry();
+
+        // Start animation loop
+        requestAnimationFrame(this.loop.bind(this));
+      }
+
+      initUI() {
+        // UI Sliders
+        this.inputSpeed = document.getElementById('input-speed');
+        this.inputCols = document.getElementById('input-cols');
+        this.inputRows = document.getElementById('input-rows');
+        this.inputLayers = document.getElementById('input-layers');
+        this.inputMass = document.getElementById('input-mass');
+
+        // UI Displays
+        this.valSpeed = document.getElementById('val-speed');
+        this.valSpeedKmh = document.getElementById('val-speed-kmh');
+        this.valCols = document.getElementById('val-cols');
+        this.valWallWidth = document.getElementById('val-wall-width');
+        this.valRows = document.getElementById('val-rows');
+        this.valWallHeight = document.getElementById('val-wall-height');
+        this.valLayers = document.getElementById('val-layers');
+        this.valMass = document.getElementById('val-mass');
+        this.valTotalWallMass = document.getElementById('val-total-wall-mass');
+
+        // Telemetry Displays
+        this.telSpeed = document.getElementById('tel-speed');
+        this.telGForce = document.getElementById('tel-gforce');
+        this.telEnergy = document.getElementById('tel-energy');
+        this.telTime = document.getElementById('tel-time');
+        this.telMoving = document.getElementById('tel-moving');
+        this.telTotalBricks = document.getElementById('tel-total-bricks');
+        this.telMomentum = document.getElementById('tel-momentum');
+        this.statusPill = document.getElementById('telemetry-status');
+        this.speedBarFill = document.getElementById('speed-bar-fill');
+
+        // Buttons
+        this.btnTest = document.getElementById('btn-test');
+        this.btnReset = document.getElementById('btn-reset');
+        this.btnPause = document.getElementById('btn-pause');
+        this.btnStep = document.getElementById('btn-step');
+        this.btnAudio = document.getElementById('btn-audio');
+        this.iconPause = document.getElementById('icon-pause');
+        this.iconPlay = document.getElementById('icon-play');
+        this.iconAudioOn = document.getElementById('icon-audio-on');
+        this.iconAudioOff = document.getElementById('icon-audio-off');
+
+        this.settingsPanel = document.getElementById('settings-panel');
+        this.btnToggleSettings = document.getElementById('btn-toggle-settings');
+        this.btnCloseSettings = document.getElementById('btn-close-settings');
+        this.btnFollowCam = document.getElementById('btn-follow-cam');
+
+        this.updateSettingsUI();
+      }
+
+      updateSettingsUI() {
+        this.inputSpeed.value = CONFIG.carSpeed;
+        this.inputCols.value = CONFIG.wallCols;
+        this.inputRows.value = CONFIG.wallRows;
+        this.inputLayers.value = CONFIG.wallLayers;
+        this.inputMass.value = CONFIG.brickMass;
+
+        this.valSpeed.textContent = CONFIG.carSpeed;
+        this.valSpeedKmh.textContent = (CONFIG.carSpeed * 3.6).toFixed(1);
+        this.valCols.textContent = CONFIG.wallCols;
+        this.valWallWidth.textContent = (CONFIG.wallCols * CONFIG.brickW).toFixed(2);
+        this.valRows.textContent = CONFIG.wallRows;
+        this.valWallHeight.textContent = (CONFIG.wallRows * CONFIG.brickH).toFixed(2);
+        this.valLayers.textContent = CONFIG.wallLayers;
+        this.valMass.textContent = CONFIG.brickMass;
+
+        const totalBricks = CONFIG.wallCols * CONFIG.wallRows * CONFIG.wallLayers;
+        const totalMass = totalBricks * CONFIG.brickMass;
+        this.valTotalWallMass.textContent = `${totalMass.toLocaleString()} kg (${totalBricks} bricks)`;
+      }
+
+      bindEvents() {
+        window.addEventListener('resize', () => this.renderer.resize());
+
+        // Launch & Reset
+        this.btnTest.addEventListener('click', () => this.launchTest());
+        this.btnReset.addEventListener('click', () => {
+          this.world.reset();
+          this.isPaused = false;
+          this.updatePauseUI();
+          this.updateTelemetry();
+        });
+
+        // Pause & Step
+        this.btnPause.addEventListener('click', () => {
+          this.isPaused = !this.isPaused;
+          this.updatePauseUI();
+        });
+
+        this.btnStep.addEventListener('click', () => {
+          this.isPaused = true;
+          this.updatePauseUI();
+          this.world.step(1 / 60);
+          this.updateTelemetry();
+        });
+
+        // Time scale pills
+        document.querySelectorAll('.speed-pill').forEach(pill => {
+          pill.addEventListener('click', (e) => {
+            document.querySelectorAll('.speed-pill').forEach(p => p.classList.remove('active'));
+            pill.classList.add('active');
+            this.timeScale = parseFloat(pill.dataset.rate);
+          });
+        });
+
+        // Audio toggle
+        this.btnAudio.addEventListener('click', () => {
+          this.world.audio.muted = !this.world.audio.muted;
+          if (this.world.audio.muted) {
+            this.world.audio.stopEngine();
+            this.iconAudioOn.style.display = 'none';
+            this.iconAudioOff.style.display = 'block';
+          } else {
+            this.world.audio.init();
+            if (this.world.state === 'ACCELERATING') this.world.audio.startEngine();
+            this.iconAudioOn.style.display = 'block';
+            this.iconAudioOff.style.display = 'none';
+          }
+        });
+
+        // Sliders Real-time Binding
+        const handleSliderChange = () => {
+          CONFIG.carSpeed = parseFloat(this.inputSpeed.value);
+          CONFIG.wallCols = parseInt(this.inputCols.value, 10);
+          CONFIG.wallRows = parseInt(this.inputRows.value, 10);
+          CONFIG.wallLayers = parseInt(this.inputLayers.value, 10);
+          CONFIG.brickMass = parseFloat(this.inputMass.value);
+
+          this.updateSettingsUI();
+          if (this.world.state === 'READY') {
+            this.world.reset();
+            this.updateTelemetry();
+          }
+        };
+
+        this.inputSpeed.addEventListener('input', handleSliderChange);
+        this.inputCols.addEventListener('input', handleSliderChange);
+        this.inputRows.addEventListener('input', handleSliderChange);
+        this.inputLayers.addEventListener('input', handleSliderChange);
+        this.inputMass.addEventListener('input', handleSliderChange);
+
+        // Presets
+        document.querySelectorAll('.preset-btn').forEach(btn => {
+          btn.addEventListener('click', () => {
+            document.querySelectorAll('.preset-btn').forEach(b => b.classList.remove('active'));
+            btn.classList.add('active');
+            const p = btn.dataset.preset;
+
+            if (p === 'default') {
+              Object.assign(CONFIG, DEFAULTS);
+            } else if (p === 'highspeed') {
+              CONFIG.carSpeed = 42.0;
+              CONFIG.wallCols = 12;
+              CONFIG.wallRows = 8;
+              CONFIG.wallLayers = 2;
+              CONFIG.brickMass = 2.5;
+            } else if (p === 'fortress') {
+              CONFIG.carSpeed = 26.0;
+              CONFIG.wallCols = 16;
+              CONFIG.wallRows = 10;
+              CONFIG.wallLayers = 4;
+              CONFIG.brickMass = 5.0;
+            } else if (p === 'heavybricks') {
+              CONFIG.carSpeed = 24.0;
+              CONFIG.wallCols = 12;
+              CONFIG.wallRows = 8;
+              CONFIG.wallLayers = 2;
+              CONFIG.brickMass = 9.0;
+            } else if (p === 'lowspeed') {
+              CONFIG.carSpeed = 10.0;
+              CONFIG.wallCols = 10;
+              CONFIG.wallRows = 6;
+              CONFIG.wallLayers = 1;
+              CONFIG.brickMass = 2.5;
+            } else if (p === 'talltower') {
+              CONFIG.carSpeed = 30.0;
+              CONFIG.wallCols = 8;
+              CONFIG.wallRows = 16;
+              CONFIG.wallLayers = 2;
+              CONFIG.brickMass = 3.0;
+            }
+
+            this.updateSettingsUI();
+            this.world.reset();
+            this.updateTelemetry();
+          });
+        });
+
+        // Settings Panel Toggle
+        this.btnToggleSettings.addEventListener('click', () => {
+          this.settingsPanel.classList.toggle('collapsed');
+        });
+        this.btnCloseSettings.addEventListener('click', () => {
+          this.settingsPanel.classList.add('collapsed');
+        });
+
+        // Camera Controls
+        this.btnFollowCam.addEventListener('click', () => {
+          this.camera.autoFollow = !this.camera.autoFollow;
+          this.btnFollowCam.classList.toggle('active', this.camera.autoFollow);
+        });
+
+        document.getElementById('btn-zoom-in').addEventListener('click', () => {
+          this.camera.targetZoom = Math.min(2.5, this.camera.zoom * 1.25);
+          this.camera.autoFollow = false;
+          this.btnFollowCam.classList.remove('active');
+        });
+        document.getElementById('btn-zoom-out').addEventListener('click', () => {
+          this.camera.targetZoom = Math.max(0.4, this.camera.zoom / 1.25);
+          this.camera.autoFollow = false;
+          this.btnFollowCam.classList.remove('active');
+        });
+        document.getElementById('btn-zoom-fit').addEventListener('click', () => {
+          this.camera.targetX = 14.0;
+          this.camera.targetY = 2.2;
+          this.camera.targetZoom = 0.85;
+          this.camera.autoFollow = false;
+          this.btnFollowCam.classList.remove('active');
+        });
+
+        // Mouse Drag to Pan Scene
+        let isDragging = false, lastMouseX = 0, lastMouseY = 0;
+        this.canvas.addEventListener('mousedown', (e) => {
+          isDragging = true;
+          lastMouseX = e.clientX;
+          lastMouseY = e.clientY;
+        });
+        window.addEventListener('mousemove', (e) => {
+          if (!isDragging) return;
+          const dx = e.clientX - lastMouseX;
+          const dy = e.clientY - lastMouseY;
+          lastMouseX = e.clientX;
+          lastMouseY = e.clientY;
+
+          const scale = CONFIG.scale * this.camera.zoom;
+          this.camera.targetX -= dx / scale;
+          this.camera.targetY += dy / scale;
+          this.camera.x = this.camera.targetX;
+          this.camera.y = this.camera.targetY;
+          this.camera.autoFollow = false;
+          this.btnFollowCam.classList.remove('active');
+        });
+        window.addEventListener('mouseup', () => { isDragging = false; });
+
+        // Wheel Zoom
+        this.canvas.addEventListener('wheel', (e) => {
+          e.preventDefault();
+          const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
+          this.camera.targetZoom = Math.max(0.4, Math.min(2.5, this.camera.targetZoom * zoomFactor));
+        }, { passive: false });
+
+        // Keyboard Shortcuts
+        window.addEventListener('keydown', (e) => {
+          if (e.target.tagName === 'INPUT') return;
+          if (e.code === 'Space') {
+            e.preventDefault();
+            this.launchTest();
+          } else if (e.key === 'r' || e.key === 'R') {
+            this.world.reset();
+            this.isPaused = false;
+            this.updatePauseUI();
+            this.updateTelemetry();
+          } else if (e.key === 'p' || e.key === 'P') {
+            this.isPaused = !this.isPaused;
+            this.updatePauseUI();
+          } else if (e.key === 'f' || e.key === 'F') {
+            this.isPaused = true;
+            this.updatePauseUI();
+            this.world.step(1 / 60);
+            this.updateTelemetry();
+          } else if (e.key === 'c' || e.key === 'C') {
+            this.camera.autoFollow = !this.camera.autoFollow;
+            this.btnFollowCam.classList.toggle('active', this.camera.autoFollow);
+          } else if (e.key === 's' || e.key === 'S') {
+            this.settingsPanel.classList.toggle('collapsed');
+          }
+        });
+      }
+
+      launchTest() {
+        this.isPaused = false;
+        this.updatePauseUI();
+        this.world.launch();
+        this.updateTelemetry();
+      }
+
+      updatePauseUI() {
+        if (this.isPaused) {
+          this.iconPause.style.display = 'none';
+          this.iconPlay.style.display = 'block';
+        } else {
+          this.iconPause.style.display = 'block';
+          this.iconPlay.style.display = 'none';
+        }
+      }
+
+      updateTelemetry() {
+        const car = this.world.car;
+        const curSpeed = car ? Math.max(0, car.vel.x) : 0;
+        this.telSpeed.textContent = curSpeed.toFixed(1);
+
+        const speedPct = Math.min(100, (curSpeed / 45.0) * 100);
+        this.speedBarFill.style.width = `${speedPct}%`;
+
+        this.telGForce.textContent = this.world.peakGForce.toFixed(1);
+        
+        // Kinetic Energy = 0.5 * m * v² in kJ
+        const ke = car ? (0.5 * car.mass * car.vel.lengthSq()) / 1000 : 0;
+        this.telEnergy.textContent = ke.toFixed(1);
+
+        // Momentum = m * v in k·N·s
+        const mom = car ? (car.mass * curSpeed) / 1000 : 0;
+        this.telMomentum.textContent = mom.toFixed(1);
+
+        this.telTime.textContent = this.world.time.toFixed(2);
+
+        // Count moving bricks (> 0.2 m/s)
+        const bricks = this.world.bodies.filter(b => b.kind === 'brick');
+        const movingCount = bricks.filter(b => b.vel.lengthSq() > 0.04).length;
+        this.telMoving.textContent = movingCount;
+        this.telTotalBricks.textContent = bricks.length;
+
+        // Status pill
+        this.statusPill.textContent = this.world.state;
+        this.statusPill.setAttribute('data-status', this.world.state);
+      }
+
+      loop(timestamp) {
+        const dtReal = Math.min(0.1, (timestamp - this.lastTimestamp) / 1000);
+        this.lastTimestamp = timestamp;
+
+        if (!this.isPaused) {
+          const dtSim = dtReal * this.timeScale;
+          this.world.step(dtSim);
+          this.updateTelemetry();
+        }
+
+        const carPos = this.world.car ? this.world.car.pos : null;
+        this.camera.update(carPos, this.world.state, dtReal);
+        this.renderer.render();
+
+        requestAnimationFrame(this.loop.bind(this));
+      }
+    }
+
+    // Initialize application when DOM is ready
+    window.addEventListener('DOMContentLoaded', () => {
+      window.app = new App();
+    });
+  </script>
+</body>
+</html>

