node -e "
const fs = require('fs');
const html = fs.readFileSync('index.html', 'utf8');
const scriptMatch = html.match(/<script>([\s\S]*?)<\/script>/);

// Mock DOM elements and Web Audio
global.window = {
  addEventListener: () => {},
  devicePixelRatio: 1
};
global.document = {
  getElementById: () => ({
    addEventListener: () => {},
    classList: { add: () => {}, remove: () => {}, toggle: () => {} },
    style: {},
    setAttribute: () => {}
  }),
  querySelectorAll: () => []
};
global.performance = { now: () => 0 };
global.requestAnimationFrame = () => {};

eval(scriptMatch[1]);

const world = new PhysicsWorld();
