const ground = world.add(new Body(25, -1, 100, 2, 0, { kind: 'ground', mu: 0.85 }));
const car = world.add(new Body(3, 0.725, 4.2, 1.45, 1250, { kind: 'car', vx: 0, mu: 0.85 }));

