const brickW = 0.50, brickH = 0.24;
const cols = 12, rows = 8, layers = 2, mass = 2.5;

for (let l = 0; l < layers; l++) {
  for (let r = 0; r < rows; r++) {
    const isStaggered = (r % 2 === 1);
    const y = (r + 0.5) * brickH;
    if (!isStaggered) {
      for (let c = 0; c < cols; c++) {
        world.add(new Body(wallOriginX + (c + 0.5) * brickW, y, brickW, brickH, mass, { kind: 'brick', layer: l }));
