    } else {
      world.add(new Body(wallOriginX + 0.125, y, 0.25, brickH, mass * 0.5, { kind: 'brick', layer: l, isHalf: true }));
      for (let c = 0; c < cols - 1; c++) {
        world.add(new Body(wallOriginX + 0.25 + (c + 0.5) * brickW, y, brickW, brickH, mass, { kind: 'brick', layer: l }));
