      world.add(new Body(wallOriginX + (cols - 0.5) * brickW + 0.125, y, 0.25, brickH, mass * 0.5, { kind: 'brick', layer: l, isHalf: true }));
    }
  }
}

console.log('Total bodies:', world.bodies.length);

