for (let f = 0; f < 60; f++) {
  world.step(FIXED);
}
let maxRestingSpeed = 0;
for (const b of world.dyn) {
  if (b.kind === 'brick') {
    const sp = Math.hypot(b.vx, b.vy);
    if (sp > maxRestingSpeed) maxRestingSpeed = sp;
  }
}
console.log('Max resting brick speed:', maxRestingSpeed);

// Launch car at 22 m/s!
car.vx = 22;
car.wake();

console.log('Car launched at 22 m/s. Simulating 3 seconds (360 steps)...');
