  world.step(FIXED);
  if (s % 60 === 0) {
    const moving = world.dyn.filter(b => b.kind === 'brick' && Math.hypot(b.vx, b.vy) > 0.2).length;
    console.log(`t=${(s*FIXED).toFixed(2)}s | Car px=${car.px.toFixed(2)}m, vx=${car.vx.toFixed(2)}m/s | moving bricks=${moving}`);
  }
}
