          B.vx += (d1 + d2) * nx * B.invM; B.vy += (d1 + d2) * ny * B.invM;
          B.av += B.invI * (p1.rbx * (d1 * ny) - p1.rby * (d1 * nx) + p2.rbx * (d2 * ny) - p2.rby * (d2 * nx));
