        } else {
          for (let i = 0; i < m.count; i++) {
            const p = m.pts[i];
            const dvx = (B.vx - B.av * p.rby) - (A.vx - A.av * p.ray);
            const dvy = (B.vy + B.av * p.rbx) - (A.vy + A.av * p.rax);
            const vn = dvx * nx + dvy * ny;
