    for (let i = 0; i < D.length; i++) {
      const b = D[i];
      if (b.static || !b.awake) continue;
      const lin = b.vx * b.vx + b.vy * b.vy;
      const ang = b.av * b.av;
      if (lin < LIN_SLEEP * LIN_SLEEP && ang < ANG_SLEEP * ANG_SLEEP) {
