        if (b.sleepT > SLEEP_T) b.sleep();
      } else {
        b.sleepT = 0;
      }
    }
  }
}

// Setup full simulation test
const world = new World();
const ground = world.add(new Body(25, -1, 100, 2, 0, { kind: "ground", mu: 0.85 }));
const car = world.add(new Body(3, 0.725, 4.2, 1.45, 1250, { kind: "car", vx: 0, mu: 0.85 }));

const wallOriginX = 16.0;
const brickW = 0.50, brickH = 0.24;
const cols = 12, rows = 8, layers = 2, mass = 2.5;

for (let l = 0; l < layers; l++) {
  for (let r = 0; r < rows; r++) {
    const isStaggered = (r % 2 === 1);
    const y = (r + 0.5) * brickH;
    if (!isStaggered) {
      for (let c = 0; c < cols; c++) {
        world.add(new Body(wallOriginX + (c + 0.5) * brickW, y, brickW, brickH, mass, { kind: "brick", layer: l }));
      }
